  "legal.dpa.metaDescription":
    "Acordo de tratamento de dados entre as barbearias (controladoras) e o Barba & Cabelo (operador).",
  "legal.home": "Início",
  "legal.backShort": "Voltar",
  "legal.updatedOn": "Atualizado em {date}",
  "legal.audienceAll": "Para todos",
